const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',accounts:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',agents:'M12 3v3M8 3h8M4 8h16v12H4zM8 12h.01M16 12h.01M8 16h8M1 12h3M20 12h3',integrations:'M8 3v5M16 3v5M6 8h12v4a6 6 0 0 1-12 0ZM12 18v4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',folder:'M3 5h6l2 3h10v12H3z',chat:'M3 4h18v13H8l-5 4z',tasks:'M9 5h12M9 12h12M9 19h12M3 5l1 1 2-2M3 12l1 1 2-2M3 19l1 1 2-2',code:'m8 5-7 7 7 7M16 5l7 7-7 7M14 3l-4 18',terminal:'m4 5 6 6-6 6M12 18h8',arrow:'M7 17 17 7M7 7h10v10',logout:'M9 3H3v18h6M13 7l5 5-5 5M7 12h14',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',refresh:'M20 7V3l-3 3a8 8 0 1 0 3 9M20 3h-5',goal:'M12 2a10 10 0 1 0 10 10M12 6a6 6 0 1 0 6 6M12 12l9-9M16 3h5v5',activity:'m2 12 4 0 3-8 5 16 3-8h5'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.folder}"/></svg>`;
const badge=s=>`<span class="badge ${E(s)}">${E(s)}</span>`;
const date=t=>new Date(t*1000).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
let threadId='main',pendingAttachments=[],revisionBase='';
let user=null,state={projects:[],accounts:[],agents:[],integrations:[],consoles:[],running:[]},view='overview',projectId='',project=null,tab='chat',events=[],eventCursor=0,source=null,authRegister=false,refreshing=false,codeTask='',codeFile='',codeFiles=[],activeConsole=null,term=null,terminalFilter='',integrationFilter='all';

async function api(path,body,method){const response=await fetch('/api/'+path,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let result;try{result=await response.json();}catch{throw Error('The server returned an invalid response');}if(!response.ok){if(response.status===401&&user)leave();throw Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail||result));}return result;}
function toast(message,error=false){const item=document.createElement('div');item.className='toast'+(error?' error':'');item.textContent=message;$('#toasts').append(item);setTimeout(()=>item.remove(),6000);}
function empty(title,caption,button=''){return `<div class="empty">${icon('folder')}<strong>${E(title)}</strong>${E(caption)}${button}</div>`;}
function button(action,label,cls='small-button',data=''){return `<button class="${cls}" data-action="${action}" ${data}>${label}</button>`;}
function selected(value,current){return value===current?' selected':'';}
function modelOptions(a){const models=a.models?.length?a.models:[{id:a.model,name:a.model==='gemini-3.8-flash-high'?'Gemini 3.8 Flash · High':a.model}];return models.map(m=>`<option value="${E(m.id)}"${selected(m.id,a.model)}>${E(m.name)}</option>`).join('');}
const accountName=id=>state.accounts.find(a=>a.id===id)?.label||'Automatic assignment';
const roleName=id=>state.agents.find(a=>a.id===id)?.name||'Default worker';

function showModal(html,wide=false){$('#modal').className=wide?'terminal-dialog':'';$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function formModal(title,caption,fields,submit,handler){showModal(`<span class="eyebrow">KOKIC WORKSPACE</span><h2>${title}</h2><p>${caption}</p><form id="dialog-form">${fields}<button class="primary wide">${submit} ↗</button><div id="dialog-error" class="error" role="alert"></div></form>`);$('#dialog-form').onsubmit=async e=>{e.preventDefault();const b=$('button.primary',e.target);b.disabled=true;try{await handler(Object.fromEntries(new FormData(e.target)));if($('#modal').open&&!activeConsole)$('#modal').close();}catch(err){if($('#dialog-error'))$('#dialog-error').textContent=err.message;else toast(err.message,true);}finally{b.disabled=false;}};}

function leave(){user=null;source?.close();$('#auth-screen').hidden=false;$('#studio').hidden=true;events=[];eventCursor=0;}
async function enter(u){user=u;$('#auth-screen').hidden=true;$('#studio').hidden=false;$('#user-email').textContent=u.email;$('#avatar').textContent=u.email.slice(0,1).toUpperCase();$('#rail-links').innerHTML=[['overview','home','Overview'],['accounts','accounts','Accounts'],['agents','agents','Agent roles'],['integrations','integrations','Integrations'],['settings','settings','Workspace settings']].map(([v,i,t])=>`<a class="nav-icon" href="#${v}" title="${t}" aria-label="${t}" data-nav="${v}">${icon(i)}</a>`).join('');$('#logout').innerHTML=icon('logout');await refresh();await navigate(location.hash.slice(1)||'overview');connectEvents();}
async function refresh(){if(!user||refreshing)return;refreshing=true;try{state=await api('state');renderSidebar();if(projectId&&view==='project'){project=await api('projects/'+projectId+'?thread='+encodeURIComponent(threadId));updateProject();}else if(view==='overview')renderOverview();else if(view==='accounts'&&!$('#page select:focus'))renderAccounts();}catch(e){toast(e.message,true);}finally{refreshing=false;}}
function renderSidebar(){const query=$('#project-search').value.toLowerCase();$('#project-count').textContent=state.projects.length;$('#account-count').textContent=state.accounts.filter(a=>a.status==='connected').length;$('#project-list').innerHTML=state.projects.filter(p=>p.name.toLowerCase().includes(query)).map(p=>`<a class="project-link ${p.id===projectId&&view==='project'?'active':''}" href="#project/${p.id}">${icon('folder')}<span>${E(p.name)}</span></a>`).join('')||'<div class="sidebar-empty">A little room for big ideas.<br>Your projects will live here.</div>';$$('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===view));}
async function navigate(route){if(route.startsWith('project/')&&route.split('/')[1]!==projectId){threadId=localStorage.getItem('kokic-thread:'+user.id+':'+route.split('/')[1])||'main';pendingAttachments=[];revisionBase='';}[view,projectId]=route.split('/');projectId=projectId||'';if(!['overview','project','accounts','agents','integrations','settings'].includes(view))view='overview';$('#breadcrumbs').innerHTML=`Workspace <span>/</span> ${E(view==='project'?state.projects.find(p=>p.id===projectId)?.name||'Project':view[0].toUpperCase()+view.slice(1))}`;renderSidebar();if(view==='project'){project=await api('projects/'+projectId+'?thread='+encodeURIComponent(threadId));renderProject();}else if(view==='overview')renderOverview();else if(view==='accounts')renderAccounts();else if(view==='agents')renderAgents();else if(view==='integrations')renderIntegrations();else renderSettings();}
function connectEvents(){source?.close();source=new EventSource('/api/events?after='+eventCursor);source.onopen=()=>$('#connection-label').textContent='Connected';source.onerror=()=>$('#connection-label').textContent='Reconnecting';source.onmessage=e=>{const event=JSON.parse(e.data);eventCursor=event.id;events.push(event);events=events.slice(-2500);if(activeConsole===event.channel&&event.kind==='terminal'&&term){term.write(event.text);updateSignIn(events.filter(x=>x.channel===activeConsole&&x.kind==='terminal').map(x=>x.text).join(''));}if(view==='project'&&tab==='terminal')renderTaskTerminal();if(view==='project'&&tab==='chat'&&event.project===projectId&&['agent_response','tool'].includes(event.kind))renderMessages();if(event.kind==='task'||event.kind==='account')refresh();};}

function renderOverview(){const connected=state.accounts.filter(a=>a.status==='connected').length;$('#page').innerHTML=`<div class="page-padding"><div class="page-intro"><div><div class="eyebrow">YOUR WORKSPACE, IN MOTION</div><h1 style="margin-top:12px">A good day to build.</h1><p>Your ideas, your models, your own little team.</p></div>${button('new-project',icon('plus')+' New project','outline-button')}</div><div class="overview-grid"><section><div class="hero-card"><div class="eyebrow">FROM A FIRST THOUGHT TO THE FINAL COMMIT</div><h1>What will you<br>bring to life today?</h1><p>Give your agents a direction.<br>Make something worth opening.</p>${button('new-project','Start a new project &nbsp; ↗','outline-button')}<div class="hero-art"><i></i><i></i><i></i></div></div><div class="stats-row">${[['Connected accounts',connected,'ready to work','accounts'],['Your projects',state.projects.length,'ideas with a home','folder'],['Agents working',state.running.length,'in real time','activity']].map(([l,n,s,i])=>`<div class="metric"><div class="metric-top">${l}${icon(i)}</div><strong>${n}</strong><small>${s}</small></div>`).join('')}</div><div class="section-title"><h2>Your recent projects</h2>${button('new-project','New project +','text-button')}</div><div class="project-cards">${state.projects.slice(0,6).map(p=>`<a class="project-card" href="#project/${p.id}"><div class="project-icon">${icon('folder')}</div><h3>${E(p.name)}</h3><p>${E(p.description||'A new idea, ready for your agents.')}</p><div class="project-card-footer"><span>${date(p.created)}</span><span>Open workspace ↗</span></div></a>`).join('')||empty('Every great build starts somewhere.','Create your first project and give your agents a purpose.',button('new-project','Create project','outline-button'))}</div><div class="getting-started">${[['1','Connect your accounts','Bring your own Antigravity accounts, with independent sign-ins.'],['2','Pick your team','Use one model everywhere, or give each account a different role.'],['3','Build. Review. Keep.','Watch the work, review the changes, and download your code.']].map(([n,t,d])=>`<div class="step-card"><span>${n}</span><strong>${t}</strong><p>${d}</p></div>`).join('')}</div></section><aside class="aside-stack"><section class="panel"><div class="panel-head"><h3>Your account team</h3><span class="tiny-number">${state.accounts.length}</span></div>${miniAccounts()}${button('accounts','Manage accounts &nbsp; ↗','text-button')}</section><section class="panel"><div class="panel-head"><h3>Around the workspace</h3>${icon('activity')}</div>${events.filter(e=>['task','account'].includes(e.kind)).slice(-5).reverse().map(e=>`<div class="mini-event">${E(e.text)}<small>${date(e.created)}</small></div>`).join('')||'<p class="muted" style="font-size:11px;line-height:1.9">Quiet for now.<br>Real activity appears as your agents get to work.</p>'}</section><section class="aside-note"><strong>Built on what you already use.</strong><p>Kokic connects the official Antigravity CLI to one workspace. Your Google sign-ins stay separate from your portal account.</p></section></aside></div></div>`;}
function miniAccounts(){return state.accounts.slice(0,5).map(a=>`<div class="mini-account"><div class="account-avatar">${E(a.label.slice(0,1).toUpperCase())}</div><div><strong>${E(a.label)}</strong><small>${E(a.model.replace('gemini-','').replaceAll('-',' '))}</small></div>${badge(a.status)}</div>`).join('')||'<div class="empty" style="padding:20px 0"><strong>A team of your own.</strong>Connect an account to get started.</div>';}

function renderAccounts(){const models=[...new Map(state.accounts.flatMap(a=>a.models?.length?a.models:[{id:a.model,name:a.model}]).map(m=>[m.id,m])).values()];$('#page').innerHTML=`<div class="page-padding"><div class="page-intro"><div><div class="eyebrow">BRING YOUR OWN INTELLIGENCE</div><h1 style="margin-top:12px">One workspace. Your accounts.</h1><p>Separate sign-ins, independent models, one connected team.</p></div>${button('add-account',icon('plus')+' Connect account','primary')}</div><div class="account-toolbar"><select id="all-model" aria-label="Model for all accounts">${models.map(m=>`<option value="${E(m.id)}">${E(m.name)}</option>`).join('')||'<option value="gemini-3.8-flash-high">Gemini 3.8 Flash · High</option>'}</select>${button('model-all','Apply model to all','outline-button')}<span class="muted" style="font-size:10px">Each account can also use its own model.</span></div><div class="account-grid">${state.accounts.map(a=>{const modelName=a.models?.find(m=>m.id===a.model)?.name;const entry=Object.entries(a.quota||{}).find(([name])=>name===modelName||name===a.model);const q=a.quota?.[a.model.startsWith('gemini-')?'gemini':'claude_gpt']||entry?.[1];return `<article class="account-card"><div class="account-card-head"><div class="account-avatar">${E(a.label.slice(0,1).toUpperCase())}</div><div><h3>${E(a.label)}</h3><p>${E(a.email||'Google sign-in not completed')}</p></div>${badge(a.status)}</div><label>Reasoning model<select data-model="${a.id}">${modelOptions(a)}</select></label>${quotaBox(a,q)}${a.status==='limited'?button('account-retry','Retry after reset','small-button',`data-id="${a.id}"`):''}${a.error?`<p class="error">${E(a.error)}</p>`:''}<div class="button-row">${button('account-console',a.status==='disconnected'?'Sign in ↗':'Open terminal','small-button',`data-id="${a.id}"`)}${button('account-models','Sync models','small-button',`data-id="${a.id}"`)}${button('account-usage',icon('refresh')+' Refresh quota','small-button',`data-id="${a.id}"`)}</div></article>`;}).join('')}<button class="add-account-card" data-action="add-account"><span class="plus">＋</span><strong>Add another perspective.</strong><p>Connect an independent Google account through the official CLI sign-in flow.</p></button></div></div>`;}
function addAccount(){formModal('Connect an account.','Give this connection a name. Google authentication opens in a separate CLI terminal. No Google password is collected by Kokic.',`<label>Account label<input name="label" placeholder="Personal Pro, Design account…" maxlength="80" required></label>`,'Continue to sign-in',async values=>{const a=await api('accounts',values);await refresh();$('#modal').close();await openConsole(a.id,'login');});}
async function openConsole(account,intent='login',sourcePlugin=''){const result=sourcePlugin?await api('accounts/'+account+'/install-plugin',{source:sourcePlugin}):await api('accounts/'+account+'/console',{intent});activeConsole=result.channel;const a=state.accounts.find(x=>x.id===account);showModal(`<div class="eyebrow">OFFICIAL ANTIGRAVITY CLI</div><h2>${E(a?.label||'Account terminal')}</h2><p>Open the Google link, then paste the returned authorization code in the box below. Keep this window open until the account shows Connected.</p><a id="oauth-link" class="auth-link" hidden target="_blank" rel="noopener noreferrer"></a><form id="oauth-code-form" hidden><div class="oauth-steps"><strong>Finish Google sign-in</strong><p>1. Open the Google link above and finish signing in.<br>2. Copy the authorization code shown on the Antigravity callback page.<br>3. Paste it here and select Complete sign-in. Signing in to Google alone does not finish the CLI connection.</p></div><label>Authorization code or callback URL<input name="code" type="password" autocomplete="off" spellcheck="false" placeholder="Paste the code from the callback page" required maxlength="8192"></label><button class="primary" id="oauth-submit">Complete sign-in</button><p id="oauth-status" role="status"></p></form><div id="cli-terminal" class="modal-terminal"></div><p class="modal-foot">${button('terminal-close','Close terminal & save session','outline-button')} &nbsp; This account has its own encrypted credential store.</p>`,true);term=new window.Terminal({fontFamily:'Consolas, monospace',fontSize:12,cols:100,rows:50,cursorBlink:true,theme:{background:'#100c14',foreground:'#d3bbdf',cursor:'#c39fe0',selectionBackground:'#573d6c'}});term.open($('#cli-terminal'));term.onData(data=>api('terminals/'+activeConsole+'/input',{data}).catch(e=>toast(e.message,true)));for(const e of events.filter(x=>x.channel===activeConsole&&x.kind==='terminal'))term.write(e.text);const cols=Math.max(40,Math.floor(($('#cli-terminal').clientWidth-20)/7.3));term.resize(cols,50);await api('terminals/'+activeConsole+'/resize',{rows:50,cols});
$('#oauth-code-form').onsubmit=async e=>{e.preventDefault();const submit=$('#oauth-submit');submit.disabled=true;try{await api('terminals/'+activeConsole+'/authorize',{code:new FormData(e.target).get('code')});e.target.reset();$('#oauth-status').textContent='Code submitted. Waiting for Antigravity to verify this account…';}catch(err){$('#oauth-status').textContent=err.message;}finally{submit.disabled=false;}};
const snapshot=await api('terminals/'+activeConsole);term.reset();term.write(snapshot.text);updateSignIn(snapshot.text);signInPoll=setInterval(()=>checkSignIn(account,intent),1500);
}

function newProject(){formModal('Make room for an idea.','A dedicated Git workspace, conversation, and agent team for whatever comes next.',`<label>Project name<input name="name" placeholder="My next great thing" maxlength="100" required></label><label>A little context<textarea name="description" rows="3" placeholder="What are we building, and who is it for?"></textarea></label>`,'Create project',async values=>{const p=await api('projects',values);await refresh();location.hash='project/'+p.id;});}
function renderProject(){if(!project)return;const p=project.project;$('#page').innerHTML=`<div class="project-header"><div class="project-heading"><div><h1>${E(p.name)}</h1><p>${E(p.description||'A workspace for your next idea.')}</p></div><div class="button-row">${button('pause-project',p.paused?'Resume queue':'Pause queue','small-button')}<a class="outline-button" href="/api/projects/${p.id}/download">${icon('download')} Download ZIP</a></div></div>${threadBar()}<div class="project-tabs">${[['chat','chat','Chat'],['tasks','tasks','Tasks'],['code','code','Code'],['terminal','terminal','Terminal'],['plan','tasks','Plan & work'],['review','goal','Review & files']].map(([v,i,t])=>`<button data-tab="${v}" class="${tab===v?'active':''}">${icon(i)}${t}</button>`).join('')}</div></div><div class="project-layout"><section id="project-main" class="project-main"></section><aside id="project-context" class="project-context"></aside></div>`;renderProjectTab();renderContext();$('#chat-thread').onchange=changeThread;}
function renderContext(){if(!$('#project-context'))return;$('#project-context').innerHTML=`<div class="section-title"><h3>CONNECTED TEAM</h3><a href="#accounts">${icon('plus')}</a></div>${miniAccounts()}<div class="context-divider"></div><div class="section-title"><h3>PROJECT GOALS</h3>${button('add-goal','+','text-button')}</div>${project.goals.map(g=>`<div class="goal-row ${g.status}"><button class="goal-toggle ${g.status==='completed'?'done':''}" data-action="toggle-goal" data-id="${g.id}" title="${g.status==='completed'?'Reopen goal':'Mark goal complete'}">${g.status==='completed'?'✓':''}</button><span>${E(g.text)}</span></div>`).join('')||'<p class="muted" style="font-size:10px;line-height:1.9">Give your team a measurable end state. Goals are included in task instructions.</p>'}<div class="context-divider"></div><div class="execution-select"><label>Execution mode<select id="autonomy"><option value="accept-edits"${selected('accept-edits',project.project.autonomy)}>Review command permissions</option><option value="autonomous"${selected('autonomous',project.project.autonomy)}>Autonomous execution</option></select></label><p>${project.project.autonomy==='autonomous'?'Agents can run commands and edit files without individual prompts. Changes remain in a review branch.':'File edits are allowed; command permissions follow the CLI. Use the account terminal for configuration.'}</p></div><div class="context-divider"></div><p class="muted" style="font-size:9px;line-height:1.9">Each task works on its own branch.<br>You decide what reaches main.</p>`;$('#autonomy').onchange=async e=>{await api('projects/'+projectId,{autonomy:e.target.value},'PUT');await refresh();};}
async function renderProjectTab(){$$('.project-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='chat')renderChatShell();else if(tab==='tasks')renderTasks();else if(tab==='code')await renderCode();else if(tab==='plan')renderPlans();else if(tab==='review')renderReview();else renderTerminalShell();}
function updateProject(){renderContext();if(tab==='chat')renderMessages();else if(tab==='tasks')renderTasks();else if(tab==='terminal')renderTaskTerminal();else if(tab==='review')renderReview();else if(tab==='plan')renderPlans();const pause=$('[data-action=pause-project]');if(pause)pause.textContent=project.project.paused?'Resume queue':'Pause queue';}
function renderChatShell(){$('#project-main').innerHTML=`<div class="chat-layout"><div id="message-list" class="message-list"></div><form id="chat-form"><input id="attachment-input" type="file" multiple hidden><div id="attachment-list"></div><div class="composer"><textarea name="prompt" id="prompt-input" placeholder="Describe what you want to build…" aria-label="Message your agents" required rows="3"></textarea><div class="composer-footer"><div class="composer-selects"><select name="account" aria-label="Assign account"><option value="">Auto assign</option>${state.accounts.map(a=>`<option value="${a.id}">${E(a.label)}</option>`).join('')}</select><select name="role" aria-label="Agent role">${state.agents.map(a=>`<option value="${a.id}">${E(a.name)}</option>`).join('')}</select><select name="policy" aria-label="Scheduling"><option value="sequential">Sequential</option><option value="parallel">Parallel</option><option value="fallback">Available account</option></select></div><div class="flex"><button type="button" class="icon-button" data-action="attach-md" title="Attach files">＋</button><button class="primary" id="send-task">Send ↗</button></div></div></div><div class="composer-hint"><span>Agents work in isolated branches. Review changes before merging.</span><span>⌘ / Ctrl + Enter to send</span></div></form></div>`;renderMessages();$('#chat-form').onsubmit=sendChat;$('#attachment-input').onchange=uploadAttachments;renderAttachments();$('#prompt-input').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey))$('#chat-form').requestSubmit();};}
function renderMessages(){const list=$('#message-list');if(!list)return;const expanded=new Set([...list.querySelectorAll('details[open]')].map(d=>d.dataset.message));const bottom=list.scrollHeight-list.scrollTop-list.clientHeight<100;list.innerHTML=project.messages.length?project.messages.map(m=>{const t=project.tasks.find(t=>t.id===m.task);return `<article class="message ${m.role}"><div class="message-avatar">${m.role==='user'?'Y':'k'}</div><div class="message-body"><div class="message-head"><strong>${m.role==='user'?'You':'Kokic Agent'}</strong><time>${date(m.created)}</time></div><div class="message-content">${m.role==='user'?E(m.content):messageMarkup(m,t)}</div>${messageFiles(m)}${messageActions(m,t)}${t&&t.phase!=='chat'?`<button class="message-task" data-action="show-task-terminal" data-id="${t.id}">${icon('terminal')}${E(t.title.slice(0,45))} ${badge(t.status)}</button>`:''}</div></article>`;}).join(''):`<div class="chat-welcome"><div class="logo-mark">k</div><h2>Your next idea starts here.</h2><p>A website, an app, a fix, or something completely new.<br>Give your team a clear direction and let the work begin.</p><div class="suggestions">${['Build a polished website for my business','Create an app with login and a dashboard','Review the code and suggest improvements','Make a plan before writing any code'].map(s=>`<button class="suggestion" data-action="suggest" data-prompt="${E(s)}">${E(s)} &nbsp; ↗</button>`).join('')}</div></div>`;list.innerHTML+=questionCards()+workflowProgress();for(const d of list.querySelectorAll('details[data-message]'))d.open=expanded.has(d.dataset.message);if(bottom)list.scrollTop=list.scrollHeight;}
async function sendChat(e){e.preventDefault();const b=$('#send-task');b.disabled=true;try{const values=Object.fromEntries(new FormData(e.target));await api('projects/'+projectId+'/chat',{...values,thread:threadId,attachments:pendingAttachments.map(a=>a.id),base_task:revisionBase});$('#prompt-input').value='';pendingAttachments=[];revisionBase='';renderAttachments();await refresh();}catch(e){toast(e.message,true);}finally{b.disabled=false;}}
function renderTasks(){$('#project-main').innerHTML=`<div class="section-title"><h2>Work in progress <span class="tiny-number">${project.tasks.filter(t=>t.phase!=='chat').length}</span></h2><span class="muted" style="font-size:10px">Isolated branches · human review</span></div>${project.tasks.filter(t=>t.phase!=='chat').map(t=>`<article class="task-card ${t.parent?'child':''}"><div class="flex spread"><h3>${E(t.title)}</h3>${badge(t.status)}</div><div class="task-meta"><span>${E(accountName(t.account))}</span><span>${E(roleName(t.role))}</span><span>Attempt ${t.attempt}</span>${t.parent?'<span>↳ Delegated task</span>':''}</div>${t.error?`<p class="error">${E(t.error)}</p>`:t.result?`<p>${E(t.result)}</p>`:''}<div class="button-row">${button('show-task-terminal','Terminal','small-button',`data-id="${t.id}"`)}${t.path?button('task-code','Inspect code','small-button',`data-id="${t.id}"`):''}${t.commit_hash?button('task-diff','View diff','small-button',`data-id="${t.id}"`):''}${t.status==='review'?button('task-merge','Approve & finalize ↗','small-button',`data-id="${t.id}"`):''}${['queued','running','questions'].includes(t.status)?button('task-cancel','Cancel','small-button',`data-id="${t.id}"`):''}${['failed','cancelled'].includes(t.status)?button('task-retry','Retry','small-button',`data-id="${t.id}"`):''}</div></article>`).join('')||empty('A clear board. A fresh start.','Send a message to create the first task.')}`;}
async function renderCode(){const main=$('#project-main');main.innerHTML=`<div class="code-toolbar"><select id="code-worktree" aria-label="Code worktree"><option value="">Main branch</option>${project.tasks.filter(t=>t.path).map(t=>`<option value="${t.id}"${selected(t.id,codeTask)}>${E(t.title.slice(0,40))}</option>`).join('')}</select><div class="button-row">${button('new-file','New file','small-button')}${button('save-file','Save file','small-button')}<a id="code-download" class="small-button" href="/api/projects/${projectId}/download${codeTask?'?task='+codeTask:''}">ZIP ↓</a></div></div><div class="code-layout"><div id="file-tree" class="file-tree"></div><div class="editor-wrap"><div id="editor-name" class="editor-header">Select a file</div><textarea id="code-editor" class="code-editor" aria-label="Source code editor" spellcheck="false"></textarea></div></div>`;$('#code-worktree').onchange=e=>{codeTask=e.target.value;codeFile='';loadFiles();$('#code-download').href='/api/projects/'+projectId+'/download'+(codeTask?'?task='+codeTask:'');};await loadFiles();}
async function loadFiles(){try{const result=await api('projects/'+projectId+'/files'+(codeTask?'?task='+codeTask:''));codeFiles=result.files;$('#file-tree').innerHTML=codeFiles.map(f=>`<button class="file-entry ${f.path===codeFile?'active':''}" data-action="open-file" data-path="${E(f.path)}" title="${E(f.path)}">${icon('code')} ${E(f.path)}</button>`).join('')||'<p class="muted" style="font-size:10px;padding:10px">No source files yet.</p>';if(codeFile)await openFile(codeFile);else if(codeFiles[0])await openFile(codeFiles[0].path);}catch(e){toast(e.message,true);}}
async function openFile(path){try{const data=await api('projects/'+projectId+'/file?path='+encodeURIComponent(path)+(codeTask?'&task='+codeTask:''));codeFile=path;$('#editor-name').textContent=path;$('#code-editor').value=data.content;$$('.file-entry').forEach(b=>b.classList.toggle('active',b.dataset.path===path));}catch(e){toast(e.message,true);}}
function renderTerminalShell(){$('#project-main').innerHTML=`<div class="terminal-controls"><select id="task-terminal-select" aria-label="Terminal task"><option value="">All task output</option>${project.tasks.map(t=>`<option value="${t.id}"${selected(t.id,terminalFilter)}>${E(t.title.slice(0,45))}</option>`).join('')}</select><label class="flex" style="font-size:10px"><input type="checkbox" id="follow-output" checked style="width:auto;margin:0"> Follow output</label></div><div id="task-terminal-output" class="terminal-output" role="log" aria-label="Agent activity output"></div>`;$('#task-terminal-select').onchange=e=>{terminalFilter=e.target.value;renderTaskTerminal();};renderTaskTerminal();}
function renderTaskTerminal(){const el=$('#task-terminal-output');if(!el)return;const y=el.scrollTop;const rows=events.filter(e=>e.project===projectId&&(!terminalFilter||e.task===terminalFilter)&&e.text).slice(-500);el.innerHTML=rows.map(e=>`<div class="terminal-line ${E(e.kind)}"><small>${date(e.created)} · ${E(e.kind)}${e.task?' · '+E(e.task.slice(0,7)):''}</small>${E(e.text)}</div>`).join('')||'Waiting for agent output…\nThe real CLI activity will appear here when a task starts.';if($('#follow-output')?.checked)el.scrollTop=el.scrollHeight;else el.scrollTop=y;}

function renderAgents(){$('#page').innerHTML=`<div class="page-padding"><div class="page-intro"><div><div class="eyebrow">GIVE YOUR TEAM A PURPOSE</div><h1 style="margin-top:12px">A role for every kind of work.</h1><p>Reusable instructions, optional model overrides, and clear responsibilities.</p></div>${button('add-agent','＋ New agent role','primary')}</div><div class="agent-grid">${state.agents.map(a=>`<article class="integration-card"><div class="flex spread"><div class="integration-icon">${icon('agents')}</div><span class="badge">${E(a.model||'ACCOUNT MODEL')}</span></div><h3>${E(a.name)}</h3><p>${E(a.description)}</p>${button('edit-agent','Edit instructions ↗','text-button',`data-id="${a.id}"`)}</article>`).join('')}</div></div>`;}
function agentForm(id=''){const a=state.agents.find(x=>x.id===id)||{};formModal(id?'Shape this role.':'A new teammate.','Define what this agent is responsible for. The account supplies its model unless you set an override.',`<input type="hidden" name="id" value="${E(id)}"><div class="field-row"><label>Name<input name="name" required value="${E(a.name||'')}" placeholder="Designer, Tester…"></label><label>Model override<input name="model" value="${E(a.model||'')}" placeholder="Use account model"></label></div><label>Description<input name="description" value="${E(a.description||'')}" placeholder="A short explanation of this role"></label><label>Instructions<textarea name="instructions" rows="8" required placeholder="What should this agent do, and how should it verify its work?">${E(a.instructions||'')}</textarea></label>`,'Save role',async values=>{if(!values.id)delete values.id;await api('agents',values);await refresh();renderAgents();});}
function renderIntegrations(){$('#page').innerHTML=`<div class="page-padding"><div class="page-intro"><div><div class="eyebrow">A WORKSPACE THAT CONNECTS</div><h1 style="margin-top:12px">Bring the rest of your toolkit.</h1><p>Skills, MCP servers, rules, plugins, and connector configurations.</p></div>${button('add-integration','＋ Add integration','primary')}</div><div class="filter-tabs">${['all','mcp','skill','rule','plugin','connector'].map(t=>`<button data-action="integration-filter" data-kind="${t}" class="${integrationFilter===t?'active':''}">${t==='all'?'Everything':t.toUpperCase()}</button>`).join('')}</div><div class="integration-grid">${state.integrations.filter(i=>integrationFilter==='all'||i.kind===integrationFilter).map(i=>`<article class="integration-card"><div class="flex spread"><div class="integration-icon">${icon('integrations')}</div><span class="badge">${E(i.kind.toUpperCase())}</span></div><h3>${E(i.name)}</h3><p>${i.kind==='plugin'?'Install through the official CLI in a selected account.':'Applied to account customizations when a worker starts. Secrets are encrypted at rest.'}</p><div class="button-row">${i.kind==='plugin'?button('install-plugin','Install in account ↗','text-button',`data-id="${i.id}"`):'<span class="muted" style="font-size:10px">Enabled for new workers</span>'}${(i.builtin?button('view-builtin','View built-in skill','text-button',`data-id="${i.id}"`):button('delete-integration','Remove','text-button danger',`data-id="${i.id}"`))}</div></article>`).join('')||empty('Make it your kind of workspace.','Connect a service with MCP, add a skill, or define your own working rules.')}</div></div>`;}
function integrationForm(){formModal('Connect a capability.','Configuration is stored encrypted. MCP servers and connectors must use a CLI-compatible server definition.',`<div class="field-row"><label>Name<input name="name" required placeholder="My integration"></label><label>Type<select name="kind" id="integration-kind"><option value="mcp">MCP server</option><option value="connector">Connector via MCP</option><option value="skill">Skill</option><option value="rule">Rule</option><option value="plugin">Plugin</option></select></label></div><label id="integration-config-label">Configuration JSON<textarea name="config" rows="9" required spellcheck="false" class="mono" placeholder='{"server":{"command":"your-server","args":[]}}'></textarea></label><p class="help">For a skill or rule: {"content":"Markdown instructions"}. For a plugin: {"source":"registry-name-or-source"}. Third-party services may require their own OAuth flow.</p>`,'Save integration',async values=>{values.config=JSON.parse(values.config);await api('integrations',values);await refresh();renderIntegrations();});}
function renderSettings(){$('#page').innerHTML=`<div class="page-padding"><div class="page-intro"><div><div class="eyebrow">BUILT TO STAY YOURS</div><h1 style="margin-top:12px">Your workspace, under the hood.</h1><p>A local studio powered by your existing Antigravity CLI.</p></div></div><section class="settings-note"><h3>Independent by design.</h3><p>Application source stays in your cloned repository. Private portal data, projects, worktrees, and CLI account profiles live in <code>~/Kokic Agent</code>, or the directory selected with <code>KOKIC_HOME</code>.</p><p>Connect provider accounts explicitly in Accounts. Existing global CLI credentials are not imported.</p><p>Models and quotas come from the CLI. Unreported percentages and reset times remain unknown. Projects keep work on task branches until you merge it.</p><p>This is a localhost workstation app. CLI processes run as your operating-system user; account credential separation is not a container sandbox.</p><p>Portal sessions expire after 12 hours. You are signed in as <strong>${E(user.email)}</strong>.</p></section></div>`;}

document.addEventListener('click',async event=>{const t=event.target.closest('[data-action]');if(!t)return;const action=t.dataset.action,id=t.dataset.id;try{
 if(action==='new-project')newProject();
 else if(action==='accounts')location.hash='accounts';
 else if(action==='add-account')addAccount();
 else if(action==='account-console')await openConsole(id,state.accounts.find(a=>a.id===id)?.status==='connected'?'configure':'login');
 else if(action==='account-usage'){await api('accounts/'+id+'/quota',{});await refresh();toast('Checking both quota windows…');}
 else if(action==='account-retry'){await api('accounts/'+id+'/retry',{});await refresh();toast('Account queued for another attempt.');}
 else if(action==='account-models'){await api('accounts/'+id+'/refresh',{});toast('Checking the account model catalog…');}
 else if(action==='model-all'){await api('accounts/model-all',{model:$('#all-model').value});await refresh();toast('Model applied to all account connections.');}
 else if(action==='terminal-close')$('#modal').close();
 else if(action==='pause-project'){await api('projects/'+projectId,{paused:!project.project.paused},'PUT');await refresh();}
 else if(action==='suggest'){$('#prompt-input').value=t.dataset.prompt;$('#prompt-input').focus();}
 else if(action==='copy-message'){const m=project.messages.find(m=>String(m.id)===id);if(m){await navigator.clipboard.writeText(m.content);toast('Message copied.');}}
 else if(action==='copy-code'){await navigator.clipboard.writeText(t.closest('.code-block').querySelector('pre code').textContent);toast('Code copied.');}
 else if(action==='attach-md')$('#attachment-input').click();
 else if(action==='add-goal')formModal('A clear finish line.','Choose a concrete result your team can work toward.',`<label>Goal<textarea name="text" rows="4" required placeholder="All tests pass and the new sign-in flow works end to end."></textarea></label>`,'Set goal',async b=>{await api('projects/'+projectId+'/goals',b);await refresh();});
 else if(action==='toggle-goal'){const g=project.goals.find(g=>g.id===id);await api('goals/'+id,{status:g.status==='completed'?'active':'completed'},'PUT');await refresh();}
 else if(action==='show-task-terminal'){terminalFilter=id;tab='terminal';renderProjectTab();}
 else if(action==='task-code'){codeTask=id;codeFile='';tab='code';renderProjectTab();}
 else if(action==='task-diff'){const d=await api('tasks/'+id+'/diff');showModal('<span class="eyebrow">CHANGE REVIEW</span><h2>The difference you made.</h2><pre class="diff-view">'+E(d.diff||'No changes from main.')+'</pre>',true);}
 else if(['task-merge','task-cancel','task-retry'].includes(action)){await api('tasks/'+id+'/'+action.slice(5),{});await refresh();toast(action==='task-merge'?'Changes merged to main.':'Task updated.');}
 else if(action==='open-file')await openFile(t.dataset.path);
 else if(action==='save-file'){if(!codeFile)throw Error('Choose a file first');await api('projects/'+projectId+'/file',{path:codeFile,task:codeTask,content:$('#code-editor').value},'PUT');toast('File saved and committed.');}
 else if(action==='new-file')formModal('A new file.','Create a file inside the selected worktree.',`<label>Relative path<input name="path" required placeholder="src/app.js"></label>`,'Create file',async b=>{await api('projects/'+projectId+'/file',{...b,task:codeTask,content:''},'PUT');codeFile=b.path;await loadFiles();});
 else if(action==='answer-suggestion'){$('#prompt-input').value+=t.dataset.question+': '+t.dataset.answer+'\n';$('#prompt-input').focus();}
 else if(action==='view-builtin'){const skill=state.integrations.find(i=>i.id===id&&i.builtin);showModal('<h2>'+E(skill.name)+'</h2><pre class="diff-view">'+E(skill.content)+'</pre>',true);}
 else if(action==='new-thread')formModal('A new conversation.','Separate context, shared project code.','<label>Chat title<input name="title" required maxlength="80"></label>','Create chat',async b=>{const t=await api('projects/'+projectId+'/threads',b);threadId=t.id;localStorage.setItem('kokic-thread:'+user.id+':'+projectId,threadId);project=await api('projects/'+projectId+'?thread='+threadId);renderProject();});
 else if(action==='remove-attachment'){pendingAttachments=pendingAttachments.filter(a=>a.id!==id);renderAttachments();}
 else if(action==='review-task'){tab='review';renderProjectTab();}
 else if(action==='revise-task'){revisionBase=id;tab='chat';renderProjectTab();$('#prompt-input').value='Please revise this result: ';$('#prompt-input').focus();}
 else if(action==='preview-site'){const p=await api('tasks/'+id+'/preview',{});showModal('<h2>Local build preview</h2><p>Review this build before approving. This preview stays on your machine.</p><a target="_blank" rel="noopener noreferrer" href="'+E(p.url)+'">Open preview in new tab</a><iframe class="artifact-preview" title="Website build preview" sandbox="allow-scripts allow-downloads" src="'+E(p.url)+'"></iframe>',true);}
 else if(action==='preview-file'){const url='/api/tasks/'+id+'/artifact/'+t.dataset.path.split('/').map(encodeURIComponent).join('/')+'?inline=true';showModal('<h2>'+E(t.dataset.path)+'</h2><iframe class="artifact-preview" title="Document review" src="'+E(url)+'"></iframe>',true);}
 else if(action==='open-workflow-file'){codeTask=id;codeFile=t.dataset.path;tab='code';await renderProjectTab();await openFile(t.dataset.path);}
 else if(action==='add-agent')agentForm();
 else if(action==='edit-agent')agentForm(id);
 else if(action==='add-integration')integrationForm();
 else if(action==='integration-filter'){integrationFilter=t.dataset.kind;renderIntegrations();}
 else if(action==='delete-integration'){await api('integrations/'+id,undefined,'DELETE');await refresh();renderIntegrations();}
 else if(action==='install-plugin')formModal('Install a native plugin.','Choose an account and the plugin source to pass to the official Antigravity installer.',`<label>Account<select name="account">${state.accounts.map(a=>`<option value="${a.id}">${E(a.label)}</option>`).join('')}</select></label><label>Plugin source<input name="source" required placeholder="Plugin registry name or source"></label>`,'Open installer',async b=>{await openConsole(b.account,'plugin',b.source);});
 }catch(e){toast(e.message,true);}});
document.addEventListener('change',async e=>{if(e.target.dataset.model)try{await api('accounts/'+e.target.dataset.model,{model:e.target.value},'PUT');toast('Account model updated.');}catch(err){toast(err.message,true);}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;renderProjectTab();}});
$('#new-project').onclick=newProject;$('#top-accounts').onclick=()=>location.hash='accounts';$('#project-search').oninput=renderSidebar;
$('#modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>{clearInterval(signInPoll);signInPoll=null;const id=activeConsole;activeConsole=null;term?.dispose();term=null;if(id)api('terminals/'+id+'/close',{}).catch(()=>{});refresh();});
$('#logout').onclick=async()=>{await api('logout',{});leave();};
$('#auth-toggle').onclick=()=>{authRegister=!authRegister;$('#auth-title').textContent=authRegister?'Build your own workspace.':'Good to see you.';$('#auth-caption').textContent=authRegister?'A private place for your accounts, agents, and ideas.':'Sign in and pick up where you left off.';$('#auth-submit').textContent=authRegister?'Create workspace ↗':'Enter workspace ↗';$('#auth-toggle').textContent=authRegister?'I already have an account':'Create a workspace account';};
$('#auth-form').onsubmit=async e=>{e.preventDefault();const b=$('#auth-submit');b.disabled=true;try{const u=await api(authRegister?'register':'login',Object.fromEntries(new FormData(e.target)));$('#auth-error').textContent='';await enter(u);}catch(e){$('#auth-error').textContent=e.message;}finally{b.disabled=false;}};
window.addEventListener('hashchange',()=>{if(user)navigate(location.hash.slice(1)).catch(e=>toast(e.message,true));});
setInterval(()=>{if(user&&!document.hidden&&!$('#modal').open)refresh();},4000);
api('me').then(enter).catch(()=>leave());

document.addEventListener('keydown',e=>{if(user&&e.key?.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!$('#modal').open&&!e.target.closest?.('input,textarea,select,[contenteditable]')){e.preventDefault();newProject();}});

let signInPoll=null;
function updateSignIn(text){
 if(!$('#oauth-link'))return;
 const urls=[...text.matchAll(/https:\/\/accounts\.google\.com[^\s\x00-\x20\x7f]+/g)].map(m=>m[0]).filter(value=>{try{const u=new URL(value);return u.searchParams.has('state')&&u.searchParams.has('code_challenge');}catch{return false;}});
 if(urls.length){
 const link=urls[urls.length-1],form=$('#oauth-code-form'),newState=new URL(link).searchParams.get('state'),first=form.hidden;
 if(form.dataset.oauthState&&form.dataset.oauthState!==newState){form.reset();$('#oauth-status').textContent='A fresh sign-in attempt started. Open the current Google link and use its new code.';}
 form.dataset.oauthState=newState;$('#oauth-link').hidden=false;$('#oauth-link').textContent='1. Open Google sign-in ↗';$('#oauth-link').href=link;form.hidden=false;
 if(first)$('#oauth-link').scrollIntoView({block:'start'});
}
}
async function checkSignIn(accountId,intent){
 if(!activeConsole||!$('#oauth-status'))return;
 try{
  const snapshot=await api('terminals/'+activeConsole);
  updateSignIn(snapshot.text);
  if(snapshot.status==='connected'){
   $('#oauth-status').textContent='Connected as '+snapshot.email+'. You can close this terminal and start building.';
   $('#oauth-submit').disabled=true;
   clearInterval(signInPoll);signInPoll=null;
   await api('accounts/'+accountId+'/refresh',{});
   $('#oauth-code-form').hidden=true;$('#oauth-link').hidden=true;
   if(intent==='login'){
    const channel=activeConsole;activeConsole=null;
    await api('terminals/'+channel+'/close',{});
    $('#modal').close();toast('Antigravity connected. Checking quota…');
    setTimeout(()=>api('accounts/'+accountId+'/quota',{}).catch(()=>{}),1000);
   }
   await refresh();
  }else if(snapshot.text.lastIndexOf('token exchange failed')>snapshot.text.lastIndexOf('Open the URL')){$('#oauth-status').textContent='Google rejected this code (expired or from a different sign-in attempt). Start a fresh sign-in and use the code from its current link.';}else if(snapshot.closed){$('#oauth-status').textContent='This sign-in terminal has exited. Close it and start a fresh sign-in.';clearInterval(signInPoll);signInPoll=null;}
 }catch(e){$('#oauth-status').textContent=e.message;}
}

function quotaBox(a,q){
 const status=a.quota_status,stamp=a.quota_checked;
 const windows=q?.windows?Object.entries(q.windows):q?[['reported',q]]:[];
 return '<div class="quota-box"><div class="quota-title"><span>QUOTA REMAINING</span><span>'+E(q?.group||'')+'</span></div>'+
 windows.map(([key,w])=>'<div class="quota-window"><div class="quota-window-heading"><span>'+({weekly:'Weekly limit',five_hour:'Five-hour limit',reported:'Reported limit'}[key])+'</span><strong>'+E(w.remaining_pct)+'<small> / 100</small></strong></div><div class="quota-track"><i style="width:'+Number(w.remaining_pct)+'%"></i></div><div class="quota-foot">'+(w.reset_at?'Resets '+date(w.reset_at):'Reset time not reported')+'</div></div>').join('')+
 (!windows.length?'<p class="muted">'+(status==='loading'?'Checking live CLI quota…':'Quota has not been fetched yet. Select Refresh quota.')+'</p>':'')+
 '<div class="quota-foot">'+(status==='loading'?'Refreshing…':q?'Read from Antigravity /usage':'')+(stamp?' · '+(status==='error'?'Last attempt ':'Updated ')+date(stamp):'')+'</div>'+
 (a.quota_error?'<p class="error">'+E(a.quota_error)+'</p>':'')+'</div>';
}

function threadBar(){return '<div class="thread-bar"><label>Project chat<select id="chat-thread" aria-label="Project chat thread">'+(project.threads||[]).map(t=>'<option value="'+t.id+'"'+selected(t.id,threadId)+'>'+E(t.title)+'</option>').join('')+'</select></label>'+button('new-thread','+ New chat','small-button')+'</div>';}
async function changeThread(e){threadId=e.target.value;localStorage.setItem('kokic-thread:'+user.id+':'+projectId,threadId);pendingAttachments=[];revisionBase='';project=await api('projects/'+projectId+'?thread='+threadId);renderProject();}
function messageFiles(m){return '<div class="message-files">'+(m.files||[]).map(f=>'<a href="/api/projects/'+projectId+'/uploads/'+f.id+'">'+E(f.name)+' ↓</a>').join('')+'</div>';}
function renderAttachments(){const node=$('#attachment-list');if(node)node.innerHTML=pendingAttachments.map(a=>'<span class="attachment-chip">'+E(a.name)+' '+button('remove-attachment','×','icon-button','data-id="'+a.id+'"')+'</span>').join('')+(revisionBase?'<span class="attachment-chip">Revising previous result</span>':'');}
async function uploadAttachments(e){
 const files=[...e.target.files];if(files.length+pendingAttachments.length>10){toast('Attach up to ten files per message.',true);return;}
 const send=$('#send-task');send.disabled=true;
 try{for(const file of files){if(file.size>20000000)throw Error('Attachment limit: 20 MB');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const saved=await api('projects/'+projectId+'/uploads',{name:file.name,data});pendingAttachments.push(saved);renderAttachments();}}catch(error){toast(error.message,true);}finally{send.disabled=false;e.target.value='';}
}
function renderPlans(){
 $('#project-main').innerHTML='<div class="section-title"><h2>Plans & work logs</h2></div>'+project.tasks.filter(t=>t.mode==='route'&&t.phase!=='chat').map(t=>{let p={};try{p=JSON.parse(t.plan||'{}');}catch{}return '<article class="task-card"><div class="flex spread"><h3>'+E(t.title)+'</h3>'+badge(t.phase||t.status)+'</div><p>'+E(p.enhanced_prompt||'Understanding this request…')+'</p>'+(p.steps?.length?'<ol>'+p.steps.map(x=>'<li>'+E(x)+'</li>').join('')+'</ol>':'')+(p.questions?.length?'<h4>Clarifying questions</h4>'+p.questions.map(q=>'<p>'+E(q.question)+'<br><small>'+E((q.options||[]).join(' · '))+'</small></p>').join(''):'')+(t.path?'<div class="button-row">'+button('open-workflow-file','Open PLAN.md','small-button','data-id="'+t.id+'" data-path="PLAN.md"')+button('open-workflow-file','Open WORK.md','small-button','data-id="'+t.id+'" data-path="WORK.md"')+'</div>':'')+'</article>';}).join('');
}
function renderReview(){
 const tasks=project.tasks.filter(t=>t.path);
 $('#project-main').innerHTML='<div class="section-title"><h2>Review & deliverables</h2></div>'+(tasks.map(t=>'<article class="task-card"><div class="flex spread"><h3>'+E(t.title)+'</h3>'+badge(t.status)+'</div><p>'+E(t.result||'Building your result…')+'</p><div class="artifact-grid">'+(t.artifacts||[]).map(a=>'<div class="artifact-card"><strong>'+E(a.name)+'</strong><small>'+E(a.type.toUpperCase())+' · '+Math.ceil(a.size/1024)+' KB</small><div class="button-row">'+(a.type==='pdf'?button('preview-file','Review PDF','small-button','data-id="'+t.id+'" data-path="'+E(a.path)+'"'):'')+'<a class="small-button" href="/api/tasks/'+t.id+'/artifact/'+a.path.split('/').map(encodeURIComponent).join('/')+'">Download ↓</a></div></div>').join('')+'</div><div class="button-row">'+((t.artifacts||[]).some(a=>a.name==='index.html')?button('preview-site','Open live local preview ↗','primary','data-id="'+t.id+'"'):'')+button('task-code','Source code','small-button','data-id="'+t.id+'"')+'<a class="small-button" href="/api/projects/'+projectId+'/download?task='+t.id+'">Download code ZIP</a>'+(t.status==='review'?button('revise-task','Request changes','small-button','data-id="'+t.id+'"')+button('task-merge','Approve & finalize','primary','data-id="'+t.id+'"'):'')+'</div></article>').join('')||empty('Your results will appear here.','Sites, PDFs, documents, and build artifacts appear when real files are generated.'));
}

function questionCards(){const t=project.tasks.find(t=>t.status==='questions');if(!t)return '';let p={};try{p=JSON.parse(t.plan);}catch{}return '<section class="clarification-card"><h3>A few details before building</h3><p>Answer below to refine the plan and continue this task.</p>'+(p.questions||[]).map(q=>'<div><strong>'+E(q.question)+'</strong><div class="button-row">'+(q.options||[]).map(option=>button('answer-suggestion',E(option),'small-button','data-question="'+E(q.question)+'" data-answer="'+E(option)+'"')).join('')+'</div></div>').join('')+'</section>';}

function workflowProgress(){
 const t=project.tasks.find(t=>['queued','running'].includes(t.status));if(!t)return '';
 const chunks=events.filter(e=>e.task===t.id&&e.kind==='agent_response').map(e=>e.text).join('').slice(-2500);
 const tools=events.filter(e=>e.task===t.id&&e.kind==='tool');let tool='';try{tool=JSON.parse(tools.at(-1)?.text||'{}').tool||'';}catch{}
 return '<article class="message assistant working"><div class="message-avatar">k</div><div class="message-body"><div class="message-head"><strong>Kokic Agent</strong>'+badge(t.phase||t.status)+'</div><div class="message-content">'+E(chunks||({understanding:'Understanding your message…',planning:'Refining your request and planning…',building:'Implementing the plan…'}[t.phase]||'Waiting for an available account…'))+'</div>'+(tool?'<small class="muted">Current tool: '+E(tool)+'</small>':'')+'</div></article>';
}

function messageMarkup(m,t){
 const body=KokicMarkdown.render(m.content,t);
 return m.content.length>3500?'<details class="long-response" data-message="'+E(m.id)+'"><summary>Full agent report</summary>'+body+'</details>':body;
}
function messageActions(m,t){
 if(m.role==='user')return '';
 return '<div class="message-actions"><button data-action="copy-message" data-id="'+E(m.id)+'">Copy reply</button>'+(t?.path&&['review','completed'].includes(t.status)?'<button data-action="task-code" data-id="'+E(t.id)+'">Browse code</button><a href="/api/projects/'+projectId+'/download?task='+encodeURIComponent(t.id)+'">Download ZIP ↓</a>':'')+(t?.artifacts?.some(f=>f.path?.endsWith('index.html'))?'<button data-action="preview-site" data-id="'+E(t.id)+'">Open live preview ↗</button>':'')+'</div>';
}
